'use strict';
(function(root){
const clone=x=>JSON.parse(JSON.stringify(x));
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function seed(brand,items){return {brand:clone(brand),activities:[],items:items.map(d=>({...clone(d),active:true,activity:'',reminder:d.reminder||[d.fixedSugar?'甜度固定':'',d.fixedIce?'冰量固定為'+d.fixedIce:'',d.variants.every(v=>v.temp==='冷')?'僅供冰飲':''].filter(Boolean).join('；'),cups:[...new Set(d.variants.map(v=>v.size))].map(size=>{const v=d.variants.find(v=>v.size===size&&v.temp==='冷')||d.variants.find(v=>v.size===size);return {size,capacity:brand.sizeLabels?.[size]?.split('·')[1]?.trim()||'',price:v.price,cal:v.cal};})}))};}
function changes(before,after){const lines=[];for(const item of after.items){const old=before.items.find(x=>x.id===item.id);if(!old)lines.push('新增商品：'+item.name);else if(!same(old,item))lines.push('修改商品：'+item.name);}if(!same(before.brand,after.brand))lines.push('修改店家設定');for(const a of after.activities){const old=before.activities.find(x=>x.id===a.id);if(!old)lines.push('新增活動：'+a.name);else if(!same(a,old))lines.push('修改活動：'+a.name);}return lines;}
function visible(data,item){return item.active!==false&&(!item.activity||data.activities.some(a=>a.id===item.activity&&a.active));}
function validate(data){if(!data.brand.name.trim())throw Error('請填寫店名');const ids=new Set();for(const d of data.items){if(ids.has(d.id))throw Error('商品識別碼重複');ids.add(d.id);if(!d.name.trim()||!d.menuCategory.trim())throw Error('每杯飲料都需要品名與分類');if(!d.cups.length)throw Error(d.name+' 至少需要一個杯型');const sizes=new Set();for(const cup of d.cups){if(!cup.size.trim()||sizes.has(cup.size.trim()))throw Error(d.name+' 的杯型不可空白或重複');sizes.add(cup.size.trim());for(const key of ['price','cal'])if(cup[key]!==null&&(!Number.isFinite(cup[key])||cup[key]<0))throw Error(d.name+' 的價格與熱量必須是非負數或留空');}for(const cup of d.cups)if(cup.price!==null&&!Number.isInteger(cup.price))throw Error('價格請填整數，不接受小數');if(d.activity&&!data.activities.some(a=>a.id===d.activity))throw Error('找不到商品所屬活動');}return true;}
function publish(state,now){validate(state.draft);const diff=changes(state.published,state.draft);if(!diff.length)throw Error('目前沒有需要發布的變更');const next=clone(state);next.published=clone(state.draft);next.history.unshift({at:now,data:clone(state.draft),changes:diff});return next;}
root.TeaAdmin={clone,seed,changes,visible,validate,publish};
})(globalThis);
